// Presentational pieces of the Doctor Calendar: month grid, week columns, day timeline, phone date strip.
import type { AppointmentDto, BlockedTimeDto } from '../../../services/apiClient'
import { friendlyStatusLabel } from '../../family/threePortalUtils'
import { dayKey, endsAt, formatLongDay, formatShortDay, formatTime, isActive, monthGrid, statusTone, weekDays } from './calendarUtils'

type ByDay = Map<string, AppointmentDto[]>
const weekdayLabels = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat']

const visitCount = (count: number) => `${count} ${count === 1 ? 'appointment' : 'appointments'}`

/** Up to three status dots, one per appointment, so a busy day stays readable. */
function StatusDots({ appointments }: { appointments: AppointmentDto[] }) {
  return (
    <span className="dcal-dots" aria-hidden="true">
      {appointments.slice(0, 3).map((appointment) => (
        <span key={appointment.id} className={`dcal-dot dcal-dot--${statusTone[appointment.status]}`} />
      ))}
    </span>
  )
}

export function StatusChip({ status }: { status: AppointmentDto['status'] }) {
  return <span className={`dcal-status dcal-status--${statusTone[status]}`}>{friendlyStatusLabel(status)}</span>
}

export function MonthGrid({ cursor, today, byDay, onSelect }: { cursor: Date; today: string; byDay: ByDay; onSelect: (date: Date) => void }) {
  const selected = dayKey(cursor)
  return (
    <div className="dcal-month">
      <div className="dcal-weekdays" aria-hidden="true">
        {weekdayLabels.map((label) => <span key={label}>{label}</span>)}
      </div>
      <div className="dcal-month-grid" role="group" aria-label="Days of the month">
        {monthGrid(cursor).map((date) => {
          const key = dayKey(date)
          const appointments = byDay.get(key) ?? []
          const classes = ['dcal-cell', date.getMonth() !== cursor.getMonth() && 'dcal-cell--outside', key === today && 'dcal-cell--today', key === selected && 'dcal-cell--selected']
          return (
            <button
              key={key}
              type="button"
              className={classes.filter(Boolean).join(' ')}
              aria-pressed={key === selected}
              aria-current={key === today ? 'date' : undefined}
              aria-label={`${formatShortDay(date)}, ${visitCount(appointments.length)}`}
              onClick={() => onSelect(date)}
            >
              <span className="dcal-cell-num">{date.getDate()}</span>
              {appointments.length > 0 && (
                <span className="dcal-cell-meta">
                  <StatusDots appointments={appointments} />
                  <span className="dcal-cell-count">{appointments.length}</span>
                </span>
              )}
            </button>
          )
        })}
      </div>
    </div>
  )
}

/** Phone and tablet: one week of large touch targets instead of a squeezed month grid. */
export function DateStrip({ cursor, today, byDay, onSelect }: { cursor: Date; today: string; byDay: ByDay; onSelect: (date: Date) => void }) {
  const selected = dayKey(cursor)
  return (
    <div className="dcal-strip" role="group" aria-label="Days of this week">
      {weekDays(cursor).map((date) => {
        const key = dayKey(date)
        const appointments = byDay.get(key) ?? []
        const classes = ['dcal-strip-day', key === selected && 'dcal-strip-day--selected', key === today && 'dcal-strip-day--today']
        return (
          <button
            key={key}
            type="button"
            className={classes.filter(Boolean).join(' ')}
            aria-pressed={key === selected}
            aria-current={key === today ? 'date' : undefined}
            aria-label={`${formatLongDay(date)}, ${visitCount(appointments.length)}`}
            onClick={() => onSelect(date)}
          >
            <span className="dcal-strip-name">{weekdayLabels[date.getDay()]}</span>
            <span className="dcal-strip-num">{String(date.getDate()).padStart(2, '0')}</span>
            <StatusDots appointments={appointments} />
          </button>
        )
      })}
    </div>
  )
}

function AppointmentBlock({ appointment, onOpen }: { appointment: AppointmentDto; onOpen: (appointment: AppointmentDto, trigger: HTMLElement) => void }) {
  const start = new Date(appointment.startsAt)
  const end = endsAt(appointment)
  const classes = ['dcal-block', `dcal-block--${statusTone[appointment.status]}`, !isActive(appointment) && 'dcal-block--inactive']
  return (
    <li className="dcal-slot">
      <span className="dcal-slot-time" aria-hidden="true">{formatTime(start)}</span>
      <button type="button" className={classes.filter(Boolean).join(' ')} onClick={(event) => onOpen(appointment, event.currentTarget)}>
        <span className="dcal-block-main">
          <span className="dcal-block-title">{appointment.memberDisplayName}</span>
          <span className="dcal-block-sub">{appointment.reason}</span>
          <StatusChip status={appointment.status} />
        </span>
        <span className="dcal-block-times">
          <span className="sr-only">From </span><span>{formatTime(start)}</span>
          <span className="sr-only"> to </span><span>{formatTime(end)}</span>
        </span>
      </button>
    </li>
  )
}

function BlockedBlock({ blocked }: { blocked: BlockedTimeDto }) {
  const start = new Date(blocked.startsAt)
  return (
    <li className="dcal-slot">
      <span className="dcal-slot-time" aria-hidden="true">{formatTime(start)}</span>
      <div className="dcal-block dcal-block--blocked">
        <span className="dcal-block-main">
          <span className="dcal-block-title">Blocked time</span>
          {blocked.reason && <span className="dcal-block-sub">{blocked.reason}</span>}
        </span>
        <span className="dcal-block-times">
          <span>{formatTime(start)}</span>
          <span>{formatTime(new Date(blocked.endsAt))}</span>
        </span>
      </div>
    </li>
  )
}

/** Chronological list for one day. Appointments and the doctor's own blocked time share the same timeline. */
export function DayTimeline({ appointments, blocked = [], onOpen, emptyText = 'No appointments on this day.' }: {
  appointments: AppointmentDto[]
  blocked?: BlockedTimeDto[]
  onOpen: (appointment: AppointmentDto, trigger: HTMLElement) => void
  emptyText?: string
}) {
  if (appointments.length === 0 && blocked.length === 0) return <p className="dcal-empty">{emptyText}</p>
  const rows = [
    ...appointments.map((appointment) => ({ at: appointment.startsAt, appointment, blocked: null })),
    ...blocked.map((item) => ({ at: item.startsAt, appointment: null, blocked: item })),
  ].sort((a, b) => new Date(a.at).getTime() - new Date(b.at).getTime())
  return (
    <ol className="dcal-timeline">
      {rows.map((row) => row.appointment
        ? <AppointmentBlock key={row.appointment.id} appointment={row.appointment} onOpen={onOpen} />
        : <BlockedBlock key={row.blocked.id} blocked={row.blocked} />)}
    </ol>
  )
}

export function WeekGrid({ cursor, today, byDay, onSelect, onOpen }: {
  cursor: Date
  today: string
  byDay: ByDay
  onSelect: (date: Date) => void
  onOpen: (appointment: AppointmentDto, trigger: HTMLElement) => void
}) {
  const selected = dayKey(cursor)
  return (
    <div className="dcal-week">
      {weekDays(cursor).map((date) => {
        const key = dayKey(date)
        const appointments = byDay.get(key) ?? []
        const classes = ['dcal-week-day', key === selected && 'dcal-week-day--selected', key === today && 'dcal-week-day--today']
        return (
          <section key={key} className={classes.filter(Boolean).join(' ')} aria-label={`${formatLongDay(date)}, ${visitCount(appointments.length)}`}>
            <button type="button" className="dcal-week-head" aria-pressed={key === selected} onClick={() => onSelect(date)}>
              <span className="dcal-week-name">{weekdayLabels[date.getDay()]}</span>
              <span className="dcal-week-num">{date.getDate()}</span>
            </button>
            {appointments.length === 0 ? <p className="dcal-week-empty">No visits</p> : (
              <ul className="dcal-week-list">
                {appointments.map((appointment) => (
                  <li key={appointment.id}>
                    <button
                      type="button"
                      className={['dcal-chip', `dcal-block--${statusTone[appointment.status]}`, !isActive(appointment) && 'dcal-block--inactive'].filter(Boolean).join(' ')}
                      onClick={(event) => onOpen(appointment, event.currentTarget)}
                    >
                      <span className="dcal-chip-time">{formatTime(new Date(appointment.startsAt))}</span>
                      <span className="dcal-block-title">{appointment.memberDisplayName}</span>
                      <span className="dcal-chip-status">{friendlyStatusLabel(appointment.status)}</span>
                    </button>
                  </li>
                ))}
              </ul>
            )}
          </section>
        )
      })}
    </div>
  )
}
